// === Node: "Get Daily Items" (n8n Code node) ===
// Daily teaser pull: top approved news+blog items from the last 24 hours (+ up to 2 videos)
// for one site's category. Set SITE below - 'comics' | 'coins' | 'collectibles'.
const SITE = 'comics';

const CONFIG = {
  comics: {
    brand: 'ComicStoresNearMe',
    domain: 'comicstoresnearme.com',
    accent: '#c03030',
    rule: '#c03030',
    gtag: 'G-3LKP95PGDN',
    categoryFilter: '&category=eq.Comics',
    categoryHeaders: false
  },
  coins: {
    brand: 'CoinsNearMe',
    domain: 'coinsnearme.co',
    accent: '#1a3a5c',        // NAVY accent. Gold is the brand-rule ONLY, never the accent.
    rule: '#c9a227',          // gold brand-rule under the logo
    gtag: 'G-6NBHQKVXET',
    categoryFilter: '&category=eq.Coins',
    categoryHeaders: false
  },
  collectibles: {
    brand: 'CollectiblesFamous',
    domain: 'collectiblesfamous.com',
    accent: '#B8872A',
    rule: '#B8872A',
    gtag: 'G-4J2DWC5P8K',
    categoryFilter: '&category=not.in.(%22N%2FA%22%2C%22Off-topic%22)',
    categoryHeaders: true,
    onePerCategory: true,
    catFeeds: {
      'Comics': 'https://comicstoresnearme.com/daily-feed',
      'Coins': 'https://coinsnearme.co/daily-feed',
      'Sports Cards': 'https://collectiblesfamous.com/sports-cards',
      'Trading Cards': 'https://collectiblesfamous.com/trading-cards',
      'Stamps': 'https://collectiblesfamous.com/stamps',
      'Toys': 'https://collectiblesfamous.com/toys',
      'Antiques & Art': 'https://collectiblesfamous.com/antiques-art',
      'Memorabilia': 'https://collectiblesfamous.com/memorabilia',
      'Vintage': 'https://collectiblesfamous.com/vintage',
      'Sneakers': 'https://collectiblesfamous.com/sneakers',
      'Jewelry': 'https://collectiblesfamous.com/jewelry',
      'Watches': 'https://collectiblesfamous.com/watches'
    }
  }
};
const cfg = CONFIG[SITE];

const SB = 'https://vtlgfwldogsdueiahidp.supabase.co/rest/v1/cf_content_items';
const KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InZ0bGdmd2xkb2dzZHVlaWFoaWRwIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzMwMjYyOTgsImV4cCI6MjA4ODYwMjI5OH0.L3rNdeNh_282W1BRsYBc64-64_l8bgHG6kMGSU4C048';

let HOURS = 24;

async function fetchRows(qs) {
  const url = SB + qs;
  const headers = { apikey: KEY, Authorization: 'Bearer ' + KEY };
  let resp;
  if (typeof this !== 'undefined' && this && this.helpers && this.helpers.httpRequest) {
    resp = await this.helpers.httpRequest({ method: 'GET', url: url, headers: headers });
  } else {
    const r = await fetch(url, { headers: headers });
    resp = await r.json();
  }
  const out = (typeof resp === 'string') ? JSON.parse(resp) : resp;
  return Array.isArray(out) ? out : [];
}

const sinceIso = new Date(Date.now() - HOURS * 3600000).toISOString();
const since48Iso = new Date(Date.now() - 2 * HOURS * 3600000).toISOString();
const SELECT = '?select=category,type,title,summary,url,source_name,author,published_at,quality_score';

// Fresh pool: news + blog items from the last 24h.
const rows = await fetchRows(
  SELECT + '&type=in.(news,blog)&status=eq.approved' + cfg.categoryFilter +
  '&published_at=gte.' + sinceIso +
  '&order=quality_score.desc.nullslast,published_at.desc&limit=' + (cfg.onePerCategory ? 40 : 7)
);

// onePerCategory: best story per category, top 6 categories.
let items = rows;
if (cfg.onePerCategory) {
  const byCat = {};
  rows.forEach(function (r) { const c = r.category || 'Other'; if (!byCat[c]) byCat[c] = r; });
  items = Object.keys(byCat).map(function (c) { return byCat[c]; })
    .sort(function (a, b) {
      return (Number(b.quality_score) || 0) - (Number(a.quality_score) || 0) ||
             new Date(b.published_at) - new Date(a.published_at);
    })
    .slice(0, 6);
}
items.forEach(function (r) { r.icymi = false; });
const freshCount = items.length;

// Thin day on a single-category site? Backfill to 5 from the 24-48h window ("In case you missed it").
// Only when there IS fresh news - never send a teaser made purely of reruns.
if (!cfg.onePerCategory && freshCount > 0 && freshCount < 5) {
  const older = await fetchRows(
    SELECT + '&type=in.(news,blog)&status=eq.approved' + cfg.categoryFilter +
    '&published_at=gte.' + since48Iso + '&published_at=lt.' + sinceIso +
    '&order=quality_score.desc.nullslast,published_at.desc&limit=' + (5 - freshCount)
  );
  older.forEach(function (r) { r.icymi = true; items.push(r); });
}

// Up to 2 recent videos (48h window so quiet days still get one).
const vids = await fetchRows(
  SELECT + '&type=eq.video&status=eq.approved' + cfg.categoryFilter +
  '&published_at=gte.' + since48Iso +
  '&order=quality_score.desc.nullslast,published_at.desc&limit=2'
);

// --- date label pinned to US Eastern ---
let dateLabel;
try {
  dateLabel = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }).format(new Date());
} catch (e) {
  const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const MON = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const now = new Date();
  dateLabel = DAYS[now.getDay()] + ', ' + MON[now.getMonth()] + ' ' + now.getDate() + ', ' + now.getFullYear();
}

const decode = (s) => String(s == null ? '' : s)
  .replace(/&#(\d+);/g, function (m, n) { return String.fromCharCode(Number(n)); })
  .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#039;/g, "'")
  .replace(/&apos;/g, "'").replace(/&nbsp;/g, ' ');

let subject = items.length ? decode(items[0].title).trim() : '';
if (subject.length > 78) subject = subject.slice(0, 75).replace(/\s+\S*$/, '') + '...';
if (!subject) subject = cfg.brand + ' Daily - ' + dateLabel;

return [{ json: {
  skip: freshCount === 0,   // workflow MUST stop on skip:true - never send an empty teaser
  site: SITE,
  cfg: cfg,
  subject: subject,
  dateLabel: dateLabel,
  freshCount: freshCount,
  items: items.map(function (r) { return {
    category: r.category,
    title: decode(r.title),
    summary: decode(r.summary),
    url: decode(r.url),
    source_name: r.source_name,
    icymi: r.icymi === true
  }; }),
  videos: vids.map(function (v) { return {
    category: v.category,
    title: decode(v.title),
    url: decode(v.url),
    channel: v.author || v.source_name
  }; })
} }];

// === Node: "Build Daily Email" (n8n Code node) ===
// Templates items[] from "Get Daily Items" into the Axios-style daily teaser email.
// Pure templating - NO AI call. Output: { skip, subject, emailHtml, site }.
// Unsubscribe is the %%UNSUBSCRIBE%% placeholder - the GHL send step replaces it.
const data = $input.first().json;
if (data.skip) return [{ json: { skip: true, site: data.site } }];

const cfg = data.cfg;
const A = cfg.accent;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const trunc = (s, n) => { s = String(s == null ? '' : s).trim(); return s.length > n ? s.slice(0, n).replace(/\s+\S*$/, '') + '...' : s; };

const UTM = '?utm_source=email&utm_medium=daily-teaser';
const feedUrl = 'https://' + cfg.domain + '/daily-feed' + UTM;
const feedFor = (cat) => (cfg.catFeeds && cat && cfg.catFeeds[cat]) ? cfg.catFeeds[cat] + UTM : feedUrl;

const eyebrow = 'font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:1.2px;color:' + A;

const items = data.items || [];
let itemsHtml = '';

if (cfg.categoryHeaders) {
  // Multi-category layout: one section per category, header links to that category's feed.
  items.forEach(function (it, i) {
    const lead = i === 0;
    itemsHtml += '<div style="' + (i ? 'border-top:1px solid #f1f1f1;margin-top:16px;' : '') + 'padding-top:' + (i ? 14 : 4) + 'px">' +
      '<div style="margin:0 0 5px"><a href="' + esc(feedFor(it.category)) + '" style="' + eyebrow + ';text-decoration:none">' + esc(it.category || 'Collectibles') + ' &rarr;</a></div>' +
      '<div style="font-size:' + (lead ? 16 : 14.5) + 'px;font-weight:700;color:#111;line-height:1.35;margin:0 0 6px">' + esc(it.title) + '</div>' +
      '<p style="font-size:' + (lead ? 14 : 13.5) + 'px;color:#333;line-height:1.65;margin:0 0 6px">' + esc(trunc(it.summary, lead ? 600 : 400)) + '</p>' +
      '<p style="font-size:12.5px;font-weight:600;margin:0"><a href="' + esc(it.url) + '" style="color:' + A + ';text-decoration:none">Read at source (' + esc(it.source_name || 'source') + ') &rarr;</a></p></div>';
  });
} else {
  // Single-category layout: lead + "Catch up fast" + optional "In case you missed it" (24-48h backfill).
  const fresh = items.filter(function (it) { return !it.icymi; });
  const icymi = items.filter(function (it) { return it.icymi; });
  const lead = fresh[0];
  const row = (it) => '<div style="padding:12px 0;border-bottom:1px solid #f1f1f1">' +
    '<div style="font-size:14px;color:#333;line-height:1.6"><b>' + esc(it.title) + '.</b> ' + esc(trunc(it.summary, 400)) + '</div>' +
    '<div style="font-size:12.5px;font-weight:600;margin-top:2px"><a href="' + esc(it.url) + '" style="color:' + A + ';text-decoration:none">Read at source (' + esc(it.source_name || 'source') + ') &rarr;</a></div></div>';
  const restHtml = fresh.slice(1).map(row).join('');
  const icymiHtml = icymi.map(row).join('');
  itemsHtml = '<div style="' + eyebrow + ';margin:18px 0 6px">Top story</div>' +
    '<div style="font-size:16px;font-weight:700;color:#111;line-height:1.35;margin:0 0 7px">' + esc(lead.title) + '</div>' +
    '<p style="font-size:14px;color:#333;line-height:1.65;margin:0 0 8px">' + esc(trunc(lead.summary, 600)) + '</p>' +
    '<p style="font-size:13px;font-weight:600;margin:2px 0 0"><a href="' + esc(lead.url) + '" style="color:' + A + ';text-decoration:none">Read at source (' + esc(lead.source_name || 'source') + ') &rarr;</a></p>' +
    (restHtml ? '<div style="' + eyebrow + ';margin:24px 0 2px">Catch up fast</div>' + restHtml : '') +
    (icymiHtml ? '<div style="' + eyebrow + ';margin:24px 0 2px">In case you missed it</div>' + icymiHtml : '');
}

// Up to 2 videos. Backward compatible with the old single `video` field.
const vidList = Array.isArray(data.videos) ? data.videos : (data.video ? [data.video] : []);
let videoHtml = '';
if (vidList.length) {
  videoHtml = '<div style="' + eyebrow + ';margin:22px 0 6px">Watch</div>';
  vidList.forEach(function (v) {
    const vidCat = (cfg.categoryHeaders && v.category) ? esc(v.category) + ' &middot; ' : '';
    videoHtml += '<div style="padding:4px 0 8px"><div style="font-size:13.5px;font-weight:600;color:#111">' + esc(v.title) + '</div>' +
      '<div style="font-size:12px;color:#777;line-height:1.6">' + vidCat + esc(v.channel || '') + ' &middot; <a href="' + esc(v.url) + '" style="color:' + A + ';text-decoration:none">Watch &rarr;</a></div></div>';
  });
}

const countLabel = items.length + (items.length === 1 ? ' story' : ' stories') + ' worth your time';

const emailHtml = '<div style="max-width:640px;margin:0 auto;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1a1a1a;background:#fafaf7;padding:14px">' +
  '<div style="text-align:center;font-size:11px;color:#888;padding:0 0 8px"><a href="' + feedUrl + '" style="color:' + A + '">View today\'s full feed &rarr;</a></div>' +
  '<div style="background:#fff;border-radius:8px;overflow:hidden;border:1px solid #eee">' +
  '<div style="border-bottom:3px solid ' + cfg.rule + ';padding:18px 26px 14px">' +
  '<div style="font-family:Georgia,serif;font-size:21px;color:#111">' + cfg.brand + ' Daily</div>' +
  '<div style="font-size:11px;text-transform:uppercase;letter-spacing:1.5px;color:#999;margin-top:3px">' + countLabel + ' &middot; ' + esc(data.dateLabel) + '</div></div>' +
  '<div style="padding:12px 26px 24px">' +
  itemsHtml +
  videoHtml +
  '<div style="text-align:center;padding:22px 0 4px"><a href="' + feedUrl + '" style="display:inline-block;background:' + A + ';color:#fff;text-decoration:none;font-weight:600;font-size:13px;padding:11px 22px;border-radius:6px">See everything on the Daily Feed</a></div>' +
  '</div></div>' +
  '<div style="text-align:center;font-size:11px;color:#999;line-height:1.7;padding:18px 16px 4px">You subscribed at ' + cfg.domain + ' &middot; %%UNSUBSCRIBE%%</div></div>';

return [{ json: { skip: false, subject: data.subject, emailHtml: emailHtml, site: data.site } }];

// === Node: "Fetch Audience" (n8n Code node) ===
// Pulls this site's DAILY audience from the source of truth (cf_newsletter_subscribers):
// digest_frequency='daily' AND status='active' AND confirmed=true AND source_site=<site>.
// Reads email + unsub_token so every send carries a REAL per-recipient unsubscribe link
// (https://<domain>/manage-subscriptions.html?token=<unsub_token>).
// NOTE: the table's RLS only lets anon INSERT, so this read needs the service key.
//
// TEST MODE: while TEST_EMAIL is set, the send goes ONLY to that address. Set it to '' to go live.
const SB_SERVICE_KEY = 'PASTE_SUPABASE_SERVICE_KEY';
const SOURCE_SITE = 'comicstoresnearme';             // per-site: comicstoresnearme | coinsnearme | collectiblesfamous
const TEST_EMAIL = 'jhgreve@gmail.com';              // <-- TEST MODE. Set to '' to send to the real audience.

const data = $input.first().json;
if (data.skip) return [{ json: { skip: true, site: data.site, reason: 'no items in the last 24h' } }];

if (SB_SERVICE_KEY.indexOf('PASTE_') === 0) throw new Error('Paste the Supabase service_role key into the Fetch Audience node first.');

const SB = 'https://vtlgfwldogsdueiahidp.supabase.co/rest/v1/cf_newsletter_subscribers';
const qs = '?select=email,unsub_token&source_site=eq.' + SOURCE_SITE +
  '&digest_frequency=eq.daily&status=eq.active&confirmed=eq.true&limit=1000';
let resp = await this.helpers.httpRequest({
  method: 'GET', url: SB + qs,
  headers: { apikey: SB_SERVICE_KEY, Authorization: 'Bearer ' + SB_SERVICE_KEY }
});
const rows = Array.isArray(resp) ? resp : JSON.parse(resp || '[]');

const realCount = rows.length;
let audience = rows.map(function (r) { return { email: String(r.email || '').trim().toLowerCase(), unsub_token: r.unsub_token || '' }; })
  .filter(function (r) { return r.email; });

const testMode = !!(TEST_EMAIL && TEST_EMAIL.trim());
if (testMode) {
  const t = TEST_EMAIL.trim().toLowerCase();
  const match = audience.find(function (r) { return r.email === t; });
  audience = [match || { email: t, unsub_token: 'TEST' }];
}

return [{ json: { skip: false, site: data.site, testMode: testMode, realCount: realCount, audience: audience } }];

// === Node: "Send via GHL" (n8n Code node) ===
// For each audience member: find (or upsert) the GHL contact by email, skip DND,
// swap %%UNSUBSCRIBE%% for their personal manage-subscriptions link, then send the
// email through GHL conversations. Throttled. Never set executeOnce on this node.
const GHL = 'PASTE_NEWSLETTER_CONTACTS_TOKEN';
const SITE_DOMAIN = 'comicstoresnearme.com';   // per-site: comicstoresnearme.com | coinsnearme.co | collectiblesfamous.com
const LOC = 'MHmcNUWmcWAPevl1QVXm';
const B = 'https://services.leadconnectorhq.com';
const H = { Authorization: 'Bearer ' + GHL, Version: '2021-07-28', 'Content-Type': 'application/json', Accept: 'application/json' };

// Same tags the live subscriber-sync workflow writes - used only when upserting a missing contact.
const SITE_TAG = { 'comicstoresnearme.com': 'comics-digest', 'coinsnearme.co': 'coins-digest', 'collectiblesfamous.com': 'collectibles-digest' }[SITE_DOMAIN];

const a = $input.first().json;
const label = 'Daily Teaser (' + SITE_DOMAIN + ')';
if (a.skip) return [{ json: { skip: true, sent: 0, reportSubject: label + ': skipped - ' + (a.reason || 'no items'), reportHtml: '<p>No approved items in the last 24 hours, so no email was sent. This is normal on quiet days.</p>' } }];

if (GHL.indexOf('PASTE_') === 0) throw new Error('Paste the Newsletter & Contacts GHL token into the Send via GHL node first.');

const built = $('Build Daily Email').first().json;

const self = this;
async function http(method, url, body) {
  return await self.helpers.httpRequest({ method: method, url: url, headers: H, body: body || undefined, json: true });
}
const sleep = (ms) => new Promise(function (res) { setTimeout(res, ms); });

let sent = 0, dndSkipped = 0, upserted = 0; const failures = [];
for (const sub of (a.audience || [])) {
  try {
    let contact = null;
    try {
      const s = await http('GET', B + '/contacts/?locationId=' + LOC + '&query=' + encodeURIComponent(sub.email));
      contact = ((s && s.contacts) || []).find(function (c) { return String(c.email || '').toLowerCase() === sub.email; }) || null;
    } catch (e) {}
    if (!contact) {
      const up = await http('POST', B + '/contacts/upsert', { locationId: LOC, email: sub.email, tags: [SITE_TAG, 'digest-daily', 'newsletter'] });
      contact = (up && up.contact) || null;
      upserted++;
    }
    if (!contact || !contact.id) { failures.push(sub.email + ': no GHL contact'); continue; }
    if (contact.dnd === true) { dndSkipped++; continue; }

    const unsub = '<a href="https://' + SITE_DOMAIN + '/manage-subscriptions.html?token=' + encodeURIComponent(sub.unsub_token || '') + '" style="color:#999">Unsubscribe</a>';
    const html = String(built.emailHtml).split('%%UNSUBSCRIBE%%').join(unsub);

    await http('POST', B + '/conversations/messages', { type: 'Email', contactId: contact.id, subject: built.subject, html: html });
    sent++;
  } catch (e) {
    failures.push(sub.email + ': ' + (e && e.message ? e.message.slice(0, 200) : 'error'));
  }
  await sleep(500); // throttle
}

const mode = a.testMode ? ' [TEST MODE - only ' + (a.audience[0] && a.audience[0].email) + ']' : '';
const reportSubject = label + ': ' + sent + ' sent' + mode + ' - ' + built.subject;
const reportHtml = '<p><b>' + label + '</b>' + mode + '</p>' +
  '<p>Sent: ' + sent + ' &middot; DND skipped: ' + dndSkipped + ' &middot; upserted into GHL: ' + upserted +
  ' &middot; real daily audience: ' + a.realCount + (failures.length ? ' &middot; <b style="color:#b00">failures: ' + failures.length + '</b>' : '') + '</p>' +
  (failures.length ? '<p style="color:#b00;font-size:12px">' + failures.join('<br>') + '</p>' : '') +
  '<hr><p><b>What subscribers got:</b> (subject: ' + built.subject + ')</p>' + built.emailHtml;

return [{ json: { skip: false, sent: sent, dndSkipped: dndSkipped, upserted: upserted, failures: failures, testMode: a.testMode, reportSubject: reportSubject, reportHtml: reportHtml } }];
